import fs from 'fs';
import path from 'path';

const walk = (dir: string): string[] =>
  fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => (entry.isDirectory() ? walk(path.join(dir, entry.name)) : entry.name.endsWith('.ts') ? [path.join(dir, entry.name)] : []));

const total = walk('src').reduce((sum, file) => sum + (fs.readFileSync(file, 'utf8').match(/\n/g)?.length ?? 0), 0);
console.log(total);
